function gentlestStrain(heights: number[][]): number {
  const R = heights.length, C = heights[0].length;
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const reachable = (limit: number): boolean => {
    const seen = new Uint8Array(R * C);
    const queue = [0];
    seen[0] = 1;
    for (let h = 0; h < queue.length; h++) {
      const r = Math.floor(queue[h] / C), c = queue[h] % C;
      if (r === R - 1 && c === C - 1) return true;
      for (const [dr, dc] of dirs) {
        const nr = r + dr, nc = c + dc;
        if (nr < 0 || nc < 0 || nr >= R || nc >= C || seen[nr * C + nc]) continue;
        if (Math.abs(heights[nr][nc] - heights[r][c]) > limit) continue;
        seen[nr * C + nc] = 1;
        queue.push(nr * C + nc);
      }
    }
    return false;
  };
  let lo = 0, hi = 1000000;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (reachable(mid)) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

