class MinHeap {
  private a: [number, number][] = [];
  get size() { return this.a.length; }
  push(x: [number, number]) {
    const a = this.a; a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p][0] <= a[i][0]) break;
      [a[p], a[i]] = [a[i], a[p]]; i = p;
    }
  }
  pop(): [number, number] {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && a[l][0] < a[m][0]) m = l;
        if (r < a.length && a[r][0] < a[m][0]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]]; i = m;
      }
    }
    return top;
  }
}

function gentlestStrain(heights: number[][]): number {
  const R = heights.length, C = heights[0].length;
  const best = new Array(R * C).fill(Infinity);
  best[0] = 0;
  const heap = new MinHeap();
  heap.push([0, 0]);
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  while (heap.size) {
    const [d, id] = heap.pop();
    if (d > best[id]) continue;
    if (id === R * C - 1) return d;
    const r = Math.floor(id / C), c = id % C;
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr < 0 || nc < 0 || nr >= R || nc >= C) continue;
      const nd = Math.max(d, Math.abs(heights[nr][nc] - heights[r][c]));
      if (nd < best[nr * C + nc]) {
        best[nr * C + nc] = nd;
        heap.push([nd, nr * C + nc]);
      }
    }
  }
  return 0;
}

