function gentlestStrain(heights: number[][]): number {
  const R = heights.length, C = heights[0].length, N = R * C;
  if (N === 1) return 0;
  const edges: [number, number, number][] = [];
  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) {
    if (r + 1 < R) edges.push([Math.abs(heights[r][c] - heights[r + 1][c]), r * C + c, (r + 1) * C + c]);
    if (c + 1 < C) edges.push([Math.abs(heights[r][c] - heights[r][c + 1]), r * C + c, r * C + c + 1]);
  }
  edges.sort((a, b) => a[0] - b[0]);
  const parent = Array.from({ length: N }, (_, i) => i);
  const find = (x: number): number => {
    while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; }
    return x;
  };
  for (const [w, a, b] of edges) {
    parent[find(a)] = find(b);
    if (find(0) === find(N - 1)) return w;
  }
  return 0;
}

